def match_here(p, pi, t, ti):
    if pi == len(p):
        return True
    if pi + 1 < len(p) and p[pi + 1] == "*":
        c = p[pi]
        k = ti
        while True:
            if match_here(p, pi + 2, t, k):
                return True
            if k < len(t) and (c == "." or t[k] == c):
                k += 1
            else:
                return False
    if p[pi] == "$" and pi + 1 == len(p):
        return ti == len(t)
    if ti < len(t) and (p[pi] == "." or p[pi] == t[ti]):
        return match_here(p, pi + 1, t, ti + 1)
    return False


def search(p, t):
    if p.startswith("^"):
        return match_here(p, 1, t, 0)
    for s in range(len(t) + 1):
        if match_here(p, 0, t, s):
            return True
    return False


