            neg = body.startswith("^")
            chars = body[1:] if neg else body
            u = ("set", chars, neg)
            i = j + 1
        else:
            u = ("any",) if p[i] == "." else ("ch", p[i])
            i += 1
        q = "1"
        if i < len(p) and p[i] in "?+*":
            q = p[i]
            i += 1
        units.append((u, q))
    return units


