def tokenize(s):
    toks = []
    i = 0
    while i < len(s):
        c = s[i]
        if c == " ":
            i += 1
        elif c.isdigit():
            j = i
            while j < len(s) and s[j].isdigit():
                j += 1
            toks.append(s[i:j])
            i = j
        else:
            toks.append(c)
            i += 1
    return toks


def div0(a, b):
    q = abs(a) // abs(b)
    return q if (a >= 0) == (b >= 0) else -q


def main():
    toks = tokenize(input())
    pos = [0]

    def peek():
        return toks[pos[0]] if pos[0] < len(toks) else None

    def take():
        pos[0] += 1
        return toks[pos[0] - 1]

    def factor():
        t = take()
        if t == "(":
            v = expr()
            take()
            return v
        return int(t)

    def term():
        v = factor()
        while peek() in ("*", "/"):
            o = take()
            r = factor()
            v = v * r if o == "*" else div0(v, r)
        return v

    def expr():
        v = term()
        while peek() in ("+", "-"):
            o = take()
            r = term()
            v = v + r if o == "+" else v - r
        return v

    print(expr())

