def apply(cmd, L):
    w = cmd.split()
    if w[0] == "upper":
        return [x.upper() for x in L]
    if w[0] == "lower":
        return [x.lower() for x in L]
    if w[0] == "rev":
        return [x[::-1] for x in L]
    if w[0] == "sort":
        return sorted(L)
    if w[0] == "uniq":
        out = []
        for x in L:
            if not out or out[-1] != x:
                out.append(x)
        return out
    if w[0] == "tac":
        return L[::-1]
    if w[0] == "head":
        return L[:int(w[1])]
    if w[0] == "tail":
        return L[-int(w[1]):]
    if w[0] == "wc":
        return [str(len(L))]
    return [x for x in L if w[1] in x]


def main():
