def crc32(s):
    c = 0xFFFFFFFF
    for ch in s:
        c ^= ord(ch)
        for _ in range(8):
            c = (c >> 1) ^ 0xEDB88320 if c & 1 else c >> 1
    return c ^ 0xFFFFFFFF


def le(v, n):
    return [(v >> (8 * i)) & 255 for i in range(n)]


